-- ============================================================================
-- ชุดข้อมูลตัวอย่าง (DEMO) — ให้เห็นว่าแต่ละหน้าหน้าตาเป็นอย่างไรเมื่อมีข้อมูลจริงไหลผ่าน
-- ============================================================================
-- • ทุกแถวที่สร้างมี id ขึ้นต้นด้วย  0000000d-e000-4000-8000-  และรถทุกคันใช้เลขเครื่อง DEMO-
--   → ลบทิ้งได้ทั้งชุดด้วย demo-cleanup.sql โดยไม่แตะข้อมูลจริง (รถ 50 คันจริงไม่ถูกแตะ)
-- • รันซ้ำไม่ได้ (กันข้อมูลซ้ำ) — ถ้ามีอยู่แล้วจะหยุดพร้อมบอกให้รัน cleanup ก่อน
-- • เรื่องราวเดียวกันทั้งระบบ: ลูกค้าคนเดิมโผล่ตั้งแต่ลีด → ขาย → ทะเบียน → ไฟแนนซ์ → รอรับเงิน
--   → เอกสาร → ศูนย์ซ่อม → เตือนเช็กระยะ · พนักงานคนเดิมโผล่ใน ลงเวลา → เงินเดือน → คอมมิชชั่น
-- • บัญชีทดลอง 8 คน ครบทั้ง 7 บทบาท รหัสผ่านเดียวกัน:  Famai@2569   — ต้องลบก่อนเปิดใช้จริง
-- • รันทั้งก้อนในทรานแซกชันเดียว — ล้มตรงไหนย้อนกลับทั้งหมด ไม่เหลือข้อมูลครึ่ง ๆ
-- • ต้องรัน migration ถึง 35 ก่อน (ใช้คอลัมน์ document.part / receivable.wholesale_order_id / payslip)
-- ============================================================================
begin;

do $$
begin
  if exists (select 1 from customer where id = '0000000d-e000-4000-8000-000000000020') then
    raise exception 'มีข้อมูลตัวอย่างอยู่แล้ว — รัน supabase/seed/demo-cleanup.sql ก่อน แล้วค่อยรันไฟล์นี้ใหม่';
  end if;
end $$;

