-- ตรวจสอบตัวเอง: จำนวนแถวที่ควรได้
do $$
declare n int;
begin
  select count(*) into n from customer where id::text like '0000000d-e000-4000-8000-%';
  raise notice 'DEMO seeded — customers: % · sales: % · service jobs: % · attendance rows: %',
    n,
    (select count(*) from sale where id::text like '0000000d-e000-4000-8000-%'),
    (select count(*) from service_job where id::text like '0000000d-e000-4000-8000-%'),
    (select count(*) from attendance a join employee e on e.id = a.employee_id where e.id::text like '0000000d-e000-4000-8000-%');
end $$;

commit;
